    expect(nextGeneration([[0, 0]])).toEqual([]);
  });

  it("kills both cells of a living pair, each having one live neighbor (underpopulation) -- [[0,0],[1,0]] -> []", () => {
    expect(nextGeneration([[0, 0], [1, 0]])).toEqual([]);
